#[global] Unset Lia Cache. #[global] Unset Nia Cache. #[global] Unset Nra Cache.
Local Ltac lia ::= pe_lia.
Import ListNotations.
Open Scope Z_scope.
Import SymExec3.SX2. Import SymExec3Sound.SX2S.

Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Module Ly := S1Layout.
Abbreviation SEGS := Plain.M.loaded_segments.

Definition PAD_RETPC : Z := 0x9f29c.
Definition DPU_RETPC : Z := 0x9e0b0.
Definition DPL_RETPC : Z := 0x9db7c.

Section NumStage.
Context {AC : AllocCeiling}.
Context {RRND : RunRandom}.
  Variable MI : MallocIface SEGS Ly.L.
  Variable ST : StaticsIface SEGS Ly.L.
  Hypothesis DN : diag_needs MI ST.

  #[local] Notation cfg fx R pc M model := (mkCfg (@mkst fx R (Z_to_bv 64 pc) M (seg_rom SEGS)) model).
  Let MSP : 0 <= MALLOC_STACK MI. Proof. pose proof (dn_mstack MI ST DN). lia. Qed.

  Section Call.
    Context {fx : FPState}.
    Variables (A : AS MI) (s : LibIface.SX ST) (R : bvmap 5 word) (M : mem) (model : Model).
    Variables (opsp ret S ds err len : Z) (B : list (Z * Z)) (K : TSet).
    Variables (m0 : sbuf) (pp0 hm0 fl fill : Z).

    Variables (padra dpretpc opret : Z) (fillw : word).

    Variables (SVop : list word) (sv9 sv18 sv19 sv20 sv21 sv22 sv23 : word).

    Variable FR : Z.
    Hypothesis HFR : FR = 80 \/ FR = 96.
    Hypothesis CB : callB MI ST A s R M model opsp ret S.
    Hypothesis HS : FR + 1520 <= S /\ FR + 256 + XS_STK MI <= S.
    Hypothesis ROC : ro_clear Ly.L M.
    Hypothesis DI0 : ds_inv A M ds err len B m0 pp0 hm0 fl fill.
    Hypothesis ABOVE : above_sp MI A opsp ds 392.
    Hypothesis BUD : len + 24 <= DS_MAXLEN.
    Hypothesis ROOM : ds_room SEGS Ly.L MI A.
    Hypothesis VAR : (padra = 0x9e090 /\ dpretpc = DPU_RETPC) \/ (padra = 0x9db5c /\ dpretpc = DPL_RETPC).
    Hypothesis Hopret : 0 <= opret < 2 ^ 64.
    Hypothesis Hopret_ok : ret_ok (Z_to_bv 64 opret).
    Hypothesis HSVop : 8 * Z.of_nat (length SVop) <= FR.

    Let w0 : Z := pp0 - str_data (ds + 72) m0.
    Let ssp : Z := opsp - FR.

    Hypothesis OPTAIL : forall A' R3 M1 M3 model' B' (J : Z -> Prop),
        ainv MI A' M3 model' -> mstd model' -> m_fs model' = m_fs model -> m_fds model' = m_fds model -> sx_inv ST s M3 ->
        ds_rep MI A' M3 ds err (len + 24) B' -> blk_xfer B B' (live MI A) (live MI A') -> junk_ok MI A J ->
        eff MI A A' M M3 (opsp - S, opsp) (fun a => ds_foot ds B a \/ ds_foot ds B' a \/ J a) ->
        agree_on (zwin ssp opsp) M1 M3 -> slots SEGS M1 opsp SVop ->
        getr R3 2%bv = Z_to_bv 64 ssp -> getr R3 3%bv = getr R 3%bv -> getr R3 4%bv = getr R 4%bv ->
        getr R3 10%bv = Z_to_bv 64 (ds + 8) -> getr R3 8%bv = Z_to_bv 64 ds ->
        getr R3 9%bv = sv9 -> getr R3 18%bv = sv18 -> getr R3 19%bv = sv19 -> getr R3 20%bv = sv20 -> getr R3 21%bv = sv21 ->
        getr R3 22%bv = sv22 -> getr R3 23%bv = sv23 ->
        (forall r, In r [24; 25; 26; 27]%bv -> getr R3 r = getr R r) ->
        mdef M3 (opsp - S) S ->
        srealizes SEGS (cfg fx R3 opret M3 model') K.

    Record nmid (nc : Z) (R1 : bvmap 5 word) (M1 : mem) : Prop := NMID {
      nm_st : stores_in (fun a => zwin (opsp - (FR + 1520)) opsp a \/ zwin (ds + 256) (ds + 260) a) M M1;
      nm_fill : fld SEGS M1 (ds + 256) 4 32;
      nm_svop : slots SEGS M1 opsp SVop;
      nm_sv : slots SEGS M1 ssp [Z_to_bv 64 opret; Z_to_bv 64 ds; sv9; sv18; sv19; sv20; sv21];
      nm_padsv : slots SEGS M1 (ssp - 160) [Z_to_bv 64 padra; fillw; Z_to_bv 64 (ds + 112); Z_to_bv 64 (ds + 8); Z_to_bv 64 (ssp - 88 + nc); Z_to_bv 64 (ssp - 88); Z_to_bv 64 0xff0c0; sv22; sv23];
      nm_r1 : getr R1 1%bv = Z_to_bv 64 A_PAD_XS_RET; nm_r2 : getr R1 2%bv = Z_to_bv 64 (ssp - 256);
      nm_r3 : getr R1 3%bv = getr R 3%bv; nm_r4 : getr R1 4%bv = getr R 4%bv;
      nm_r8 : getr R1 8%bv = Z_to_bv 64 (ds + 8); nm_r9 : getr R1 9%bv = Z_to_bv 64 (ds + 112);
      nm_r10 : getr R1 10%bv = Z_to_bv 64 (ds + 8); nm_r11 : getr R1 11%bv = Z_to_bv 64 (ssp - 133); nm_r12 : getr R1 12%bv = Z_to_bv 64 nc;
      nm_r19 : getr R1 19%bv = Z_to_bv 64 nc;
      nm_cs : forall r, In r [24; 25; 26; 27]%bv -> getr R1 r = getr R r;
      nm_nc : 1 <= nc <= 21 }.

    Lemma ctx : alloc_ceiling + S <= opsp /\ opsp < 2 ^ 47 /\ opsp mod 16 = 0 /\ 0 <= ret < 2 ^ 64 /\
                opsp <= ds /\ ds + 392 <= 2 ^ 47 /\ (forall i, 0 <= i < 392 -> ~ owned MI A (ds + i)) /\ 0 <= w0 <= len /\ 0 <= len.
Proof using AC MI ST A s R M model opsp ret S ds err len B m0 pp0 hm0 fl fill SVop FR CB DI0 ABOVE.
